ALTER TABLE response_plans ADD COLUMN IF NOT EXISTS source_status text, ADD COLUMN IF NOT EXISTS requirement_category text, ADD COLUMN IF NOT EXISTS confirmation_type text, ADD COLUMN IF NOT EXISTS classification_review_required boolean NOT NULL DEFAULT false, ADD COLUMN IF NOT EXISTS atomicity_review_required boolean NOT NULL DEFAULT false, ADD COLUMN IF NOT EXISTS provider text NOT NULL DEFAULT 'mock', ADD COLUMN IF NOT EXISTS provider_warnings jsonb NOT NULL DEFAULT '[]'::jsonb, ADD COLUMN IF NOT EXISTS updated_at timestamptz NOT NULL DEFAULT now();
UPDATE response_plans SET response_status='partial',capability_gap=COALESCE(capability_gap,'历史 gap 状态，需人工复核') WHERE response_status='gap';
ALTER TABLE response_plans DROP CONSTRAINT IF EXISTS response_plans_response_status_check;
ALTER TABLE response_plans ADD CONSTRAINT response_plans_response_status_check CHECK(response_status IN ('full','partial','confirm'));
ALTER TABLE claims ADD COLUMN IF NOT EXISTS source_status text, ADD COLUMN IF NOT EXISTS requirement_category text, ADD COLUMN IF NOT EXISTS confirmation_type text, ADD COLUMN IF NOT EXISTS classification_review_required boolean NOT NULL DEFAULT false, ADD COLUMN IF NOT EXISTS atomicity_review_required boolean NOT NULL DEFAULT false, ADD COLUMN IF NOT EXISTS provider text NOT NULL DEFAULT 'mock', ADD COLUMN IF NOT EXISTS provider_warnings jsonb NOT NULL DEFAULT '[]'::jsonb, ADD COLUMN IF NOT EXISTS updated_at timestamptz NOT NULL DEFAULT now();
ALTER TABLE claim_decisions ADD COLUMN IF NOT EXISTS gate_decision text, ADD COLUMN IF NOT EXISTS manual_decision text, ADD COLUMN IF NOT EXISTS reason_message text, ADD COLUMN IF NOT EXISTS rule_version text NOT NULL DEFAULT '4.3.0', ADD COLUMN IF NOT EXISTS decided_at timestamptz NOT NULL DEFAULT now(), ADD COLUMN IF NOT EXISTS decided_by text;
ALTER TABLE claim_decisions DROP CONSTRAINT IF EXISTS claim_decisions_gate_decision_check;
ALTER TABLE claim_decisions ADD CONSTRAINT claim_decisions_gate_decision_check CHECK(gate_decision IS NULL OR gate_decision IN ('approved','rejected'));
ALTER TABLE claim_decisions DROP CONSTRAINT IF EXISTS claim_decisions_manual_decision_check;
ALTER TABLE claim_decisions ADD CONSTRAINT claim_decisions_manual_decision_check CHECK(manual_decision IS NULL OR manual_decision IN ('approved','rejected'));
ALTER TABLE requirement_coverages ADD COLUMN IF NOT EXISTS severity text NOT NULL DEFAULT 'pass', ADD COLUMN IF NOT EXISTS source_status text, ADD COLUMN IF NOT EXISTS requirement_category text, ADD COLUMN IF NOT EXISTS is_mandatory boolean NOT NULL DEFAULT false, ADD COLUMN IF NOT EXISTS writer_eligible boolean NOT NULL DEFAULT true, ADD COLUMN IF NOT EXISTS updated_at timestamptz NOT NULL DEFAULT now();
ALTER TABLE requirement_coverages DROP CONSTRAINT IF EXISTS requirement_coverages_severity_check;
ALTER TABLE requirement_coverages ADD CONSTRAINT requirement_coverages_severity_check CHECK(severity IN ('pass','warning','critical','excluded'));
CREATE TABLE IF NOT EXISTS requirement_constraint_records (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),project_id uuid NOT NULL REFERENCES projects(id) ON DELETE CASCADE,requirement_id uuid NOT NULL REFERENCES requirements(id) ON DELETE RESTRICT,summary text NOT NULL,source_status text NOT NULL,confirmation_type text,conditions jsonb NOT NULL DEFAULT '[]'::jsonb,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(project_id,requirement_id));
CREATE INDEX IF NOT EXISTS response_plans_project_status_idx ON response_plans(project_id,response_status);
CREATE INDEX IF NOT EXISTS claims_project_requirement_idx ON claims(project_id,requirement_id);
CREATE INDEX IF NOT EXISTS constraint_records_project_idx ON requirement_constraint_records(project_id,created_at);
